#ifdef NDEBUG
#error "Keep assertions enabled in this teaching test."
#endif
#include <algorithm>
#include <cassert>
#include <iostream>
enum class Command { Coast, Boost };
struct State { int height; int energy; };
struct Frame { bool boosted; bool landed; };
class Flight {
    State s_;
public:
    Flight() : s_{5, 6} {}
    const State& state() const { return s_; }
    Frame step(Command command) {
        // 교육용 정수 규칙이다. 실제 공기역학이나 초 단위 물리가 아니다.
        const bool boost = command == Command::Boost && s_.energy >= 2;
        if (boost) { s_.energy -= 2; s_.height += 3; }
        else s_.energy = std::min(6, s_.energy + 1);
        // 모든 유효 틱에 중력 1칸. 높이는 0~12로 제한한다.
        s_.height = std::max(0, std::min(12, s_.height - 1));
        return Frame{boost, s_.height == 0};
    }
};
int main() {
    Flight fall;
    for (int i = 0; i < 4; ++i) assert(!fall.step(Command::Coast).landed);
    assert(fall.state().height == 1);
    assert(fall.step(Command::Coast).landed);
    assert(fall.step(Command::Coast).landed); // 땅 아래로 내려가지 않음
    assert(fall.state().height == 0 && fall.state().energy == 6);
    Flight rise;
    for (int i = 0; i < 3; ++i) assert(rise.step(Command::Boost).boosted);
    assert(rise.state().height == 11 && rise.state().energy == 0);
    assert(!rise.step(Command::Boost).boosted); // 에너지 부족: 활공·회복
    assert(rise.state().height == 10 && rise.state().energy == 1);
    assert(!rise.step(Command::Boost).boosted);
    assert(rise.state().energy == 2);
    assert(rise.step(Command::Boost).boosted);
    // 모든 16틱 입력열을 탐색해 범위 불변식을 점검한다.
    for (unsigned mask = 0; mask < (1u << 16); ++mask) {
        Flight f;
        for (unsigned tick = 0; tick < 16; ++tick) {
            f.step((mask & (1u << tick)) ? Command::Boost : Command::Coast);
            assert(f.state().height >= 0 && f.state().height <= 12);
            assert(f.state().energy >= 0 && f.state().energy <= 6);
        }
    }
    std::cout << "flight model: 65536 input sequences passed\n";
}
